public void init()
{
    next init();

    switch (this.args().parmEnum())
    {
        case HcmEmploymentAction::Add:
            NVHcmWorkerRehireReasonId.visible(true);
            break;
    }
}

public void closeOk()
{
    switch (this.args().parmEnum())
    {
        case HcmEmploymentAction::Add:
            NVHcmWorkerHireReasonId rehireReasonId = NVHcmWorkerRehireReasonId.text();
            if(rehireReasonId != "")
            {
                HcmWorker locWorker = HcmWorker::find(hcmWorker.RecId, true);
                if(locWorker)
                {
                    ttsbegin;
                    locWorker.NVHcmWorkerRehireReasonId = rehireReasonId;
                    locWorker.doUpdate();
                    ttscommit;
                }
            }
            break;
    }

    next closeOk();
}
